#!/usr/bin/env python3
"""Measure every gate arm once and refresh ``docs/arm-runtimes.md``.

The document is generated: this script is the only writer of the numbers it
contains. ``--check`` compares the file against a fresh render with volatile
fields (measurement time, host, interpreter) masked, so it catches hand-edited
rows and prose but not a slow host; refresh with ``./run.sh measure``.

An arm that fails aborts the run without writing anything. An arm that reports
"not installed" (exit code 2, the conformance check's contract) is recorded as
unavailable instead of guessed at.
"""

from __future__ import annotations

import argparse
import platform
import re
import subprocess
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
DOC = ROOT / "docs" / "arm-runtimes.md"
SCRIPTS = ROOT / ".github" / "scripts"

ARMS: dict[str, tuple[list[str], str]] = {
    # Order matters: `setup` is measured last, after both checks have run in this
    # environment, which makes its number a re-install rather than provisioning.
    "docs": ([sys.executable, str(SCRIPTS / "check_docs.py")], "./run.sh docs"),
    "gnn": ([sys.executable, str(SCRIPTS / "check_gnn.py")], "./run.sh gnn"),
    "setup": ([sys.executable, str(SCRIPTS / "setup_gate.py")], "./run.sh setup"),
}
COMMENT = re.compile(r"<!--.*?-->", re.DOTALL)
SECONDS = re.compile(r"\b\d+\.\d{2}\b")


def measure(command: list[str]) -> tuple[float, int]:
    started = time.perf_counter()
    result = subprocess.run(command, capture_output=True, text=True, cwd=ROOT)
    elapsed = time.perf_counter() - started
    if result.returncode not in (0, 2):
        sys.stderr.write(result.stdout + result.stderr)
        raise SystemExit(f"arm failed with exit code {result.returncode}: {' '.join(command)}")
    return elapsed, result.returncode


def render(rows: list[tuple[str, str, float | None, str]]) -> str:
    total = sum(row[2] or 0.0 for row in rows if row[0] in ARMS)
    runnable = [row for row in rows if row[0] in ARMS and row[2] is not None]
    table = ["| Arm | Command | Wall time (s) | Status |", "| --- | --- | --- | --- |"]
    for name, command, seconds, status in rows:
        cell = "—" if seconds is None else f"{seconds:.2f}"
        table.append(f"| `{name}` | `{command}` | {cell} | {status} |")

    stamp = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    host = f"{platform.system().lower()} {platform.machine()}, Python {platform.python_version()}"
    if runnable:
        measured = (
            "One run of each arm, no warm-up. The comment above records when and "
            "on which host."
        )
    else:
        measured = "No arm produced a number; see the status column for the reason."
    return "\n".join(
        [
            "# Measured arm runtimes",
            "",
            f"<!-- measured: {stamp} | {host} -->",
            "<!-- generated by .github/scripts/measure_arms.py via `./run.sh measure`; do not hand-edit -->",
            "",
            "Wall time for every gate arm on one host, one run each. This file is the",
            "repository's single home for measured numbers: prose elsewhere links here",
            "instead of copying a number. Refresh it with `./run.sh measure`; verify that",
            "its rows and prose were not hand-edited with `./run.sh measure --check`.",
            "",
            *table,
            "",
            measured,
            "",
            f"The arms above sum to {total:.2f} s. `./run.sh all` runs `docs` and `gnn`",
            "back to back; `setup` is provisioning, not a check.",
            "",
            "`setup` installs",
            "[`../.github/requirements-gate.txt`](../.github/requirements-gate.txt) and the",
            "GNN parser pinned in [`../.github/gnn-pin.json`](../.github/gnn-pin.json). It",
            "needs network access, and the `docs` arm never depends on it.",
            "",
            "See [`run-guide.md`](run-guide.md) for what each arm checks.",
            "",
        ]
    )


def produce() -> str:
    rows: list[tuple[str, str, float | None, str]] = []
    for name, (command, display) in ARMS.items():
        seconds, code = measure(command)
        if code == 2:
            rows.append((name, display, None, "not installed; run `./run.sh setup`"))
        elif name == "setup":
            rows.append((name, display, seconds, "ok (re-install of a provisioned environment)"))
        else:
            rows.append((name, display, seconds, "ok"))
    available = all(row[2] is not None for row in rows)
    if available:
        seconds, _ = measure([str(ROOT / "run.sh"), "all"])
        rows.append(("all", "./run.sh all", seconds, "ok"))
    else:
        rows.append(("all", "./run.sh all", None, "not measured; an arm is unavailable"))
    return render(rows)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--check", action="store_true", help="verify the document, do not write it")
    args = parser.parse_args(argv)

    rendered = produce()
    if args.check:
        if not DOC.is_file():
            print(f"{DOC.relative_to(ROOT)}: missing; run ./run.sh measure", file=sys.stderr)
            return 1
        current = DOC.read_text(encoding="utf-8")

        def shape(text: str) -> str:
            # Comments hold the measurement time and host; the numbers are wall
            # times that move between runs. Compare everything else.
            return SECONDS.sub("N", COMMENT.sub("", text))

        if shape(rendered) != shape(current):
            print(
                f"{DOC.relative_to(ROOT)}: rows or prose were edited by hand; "
                "run ./run.sh measure",
                file=sys.stderr,
            )
            return 1
        print(f"{DOC.relative_to(ROOT)}: matches the generator")
        return 0

    DOC.write_text(rendered, encoding="utf-8")
    print(f"wrote {DOC.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
